def zero_count(arr):
    # Initialize counters for zeroes and non-zeroes
    zero_count = 0
    non_zero_count = 0

    # Iterate through the array to count zeroes and non-zeroes
    for num in arr:
        if num == 0:
            zero_count += 1
        else:
            non_zero_count += 1

    # Calculate the ratio of zeroes to non-zeroes
    if non_zero_count == 0:
        return 0.0  # Return 0.0 if there are no non-zero elements to avoid division by zero
    ratio = zero_count / non_zero_count

    return ratio

