def find_kth(arr1, arr2, k):
    # Initialize pointers for both arrays
    i, j = 0, 0

    # Loop until we find the kth element or exhaust one of the arrays
    while i < len(arr1) and j < len(arr2) and k > 0:
        if arr1[i] < arr2[j]:
            i += 1
        else:
            j += 1
        k -= 1

    # If k is still greater than 0, it means the kth element is in the remaining part of arr2
    if k > 0:
        return arr2[j + k - 1]

    # If we have exhausted all elements of arr1, return the kth element from arr2
    if i == len(arr1):
        return arr2[j + k - 1]

    # If we have exhausted all elements of arr2, return the kth element from arr1
    if j == len(arr2):
        return arr1[i + k - 1]

    # If we have found the kth element, return it
    return arr1[i] if arr1[i] < arr2[j] else arr2[j]

