def move_zero(lst):
    # Initialize a pointer for the position to place the next non-zero element
    non_zero_position = 0

    # Iterate through the list
    for i in range(len(lst)):
        # If the current element is non-zero, place it at the non_zero_position
        if lst[i] != 0:
            lst[non_zero_position] = lst[i]
            non_zero_position += 1

    # Fill the remaining positions with zeroes
    for i in range(non_zero_position, len(lst)):
        lst[i] = 0

    return lst

